import{_ as t,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"网关跨域","description":"","frontmatter":{"title":"网关跨域","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/网关跨域.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/网关跨域.md"}'),i={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/网关跨域.md"};function a(n,e,d,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[s(`<div><p>加入网关后设置跨域 @Configuration public class RouteConfiguration { @Bean public WebFilter corsFilter() { return (ServerWebExchange ctx, WebFilterChain chain) -&gt; { ServerHttpRequest request = ctx.getRequest(); if (CorsUtils.isCorsRequest(request)) { ServerHttpResponse response = ctx.getResponse(); HttpHeaders headers = response.getHeaders(); headers.add(&quot;Access-Control-Allow-Origin&quot;, &quot;*&quot;); headers.add(&quot;Access-Control-Allow-Methods&quot;, &quot;POST, GET, PUT, OPTIONS, DELETE, PATCH&quot;); headers.add(&quot;Access-Control-Max-Age&quot;, &quot;3600&quot;); headers.add(&quot;Access-Control-Allow-Headers&quot;, &quot;Origin, X-Requested-With, Content-Type, Accept, Authorization&quot;); headers.add(&quot;Access-Control-Expose-Headers&quot;, &quot;Location&quot;); headers.add(&quot;Access-Control-Allow-Credentials&quot;, &quot;true&quot;); if (request.getMethod() == HttpMethod.OPTIONS) { response.setStatusCode(HttpStatus.OK); return Mono.empty(); } } return chain.filter(ctx); }; } } 把这段代码在网关服务中配置后跨域就成功了</p><p>总的来说，解决方案：</p><p><code>NGINX</code>解决跨域问题 在网关处解决跨域问题</p><p>这里记录自己在网关处解决跨域的方法： 技术：</p><ul><li>Springcloud Gateway</li><li>springboot</li></ul><p>版本：<code>2.1.4</code></p><p>方法<code>1</code>： 在<code>application.xml</code>：</p><ul><li>spring:</li><li>cloud: #</li></ul><p>跨域配置</p><pre><code>gateway:
  globalcors:
    cors-configurations:
      &#39;[/**]&#39;: #
</code></pre><p>匹配所有请求 <code>allowedOrigins: &quot;*&quot; #</code>跨域处理 允许所有的域 <code>allowedMethods: #</code> 支持的方法</p><ul><li><ul><li>GET</li></ul></li><li><ul><li>POST</li></ul></li><li><ul><li>PUT</li></ul></li><li><ul><li>DELETE</li></ul></li></ul><p>这样可以解决跨域的问题。</p><p>方法<code>2</code>： 在网关处新增配置类：</p><p>import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.web.cors.CorsConfiguration; import org.springframework.web.cors.reactive.CorsWebFilter; import org.springframework.web.util.pattern.PathPatternParser;</p><p>/** * 跨域允许</p><p>*/ @Configuration public class CorsConfig { @Bean public CorsWebFilter corsFilter() { CorsConfiguration config = new CorsConfiguration();</p><p><code>config.setAllowCredentials(true); //</code> 允许<code>cookies</code>跨域 <code>config.addAllowedOrigin(&quot;*&quot;);// #</code>允许向该服务器提交请求的<code>URI</code>，<code>*</code>表示全部允许，在<code>SpringMVC</code>中，如果设成<code>*</code>，会自动转成当前请求头中的</p><p>Origin config.addAllowedHeader(&quot;*&quot;);// # 允许访问的头信息<code>,*</code>表示全部 <code>config.setMaxAge(18000L);//</code> 预检请求的缓存时间（秒），即在这个时间段里，对于相同的跨域请求不会再预检了 <code>config.addAllowedMethod(&quot;OPTIONS&quot;);//</code> 允许提交请求的方法类型，<code>*</code>表示全部允许</p><pre><code>    config.addAllowedMethod(&quot;HEAD&quot;);
    config.addAllowedMethod(&quot;GET&quot;);
    config.addAllowedMethod(&quot;PUT&quot;);
    config.addAllowedMethod(&quot;POST&quot;);
    config.addAllowedMethod(&quot;DELETE&quot;);
    config.addAllowedMethod(&quot;PATCH&quot;);

    org.springframework.web.cors.reactive.UrlBasedCorsConfigurationSource source =
            new org.springframework.web.cors.reactive.UrlBasedCorsConfigurationSource(new PathPatternParser());
    source.registerCorsConfiguration(&quot;/**&quot;, config);
    return new CorsWebFilter(source);
\\}
</code></pre><p><code>}</code> 可以解决跨域问题。</p><p>记录<code>@CrossOrigin</code>发生的问题 在各个微服务对应的<code>Controller</code>，在微服务的<code>Controller</code>中，一般会加上注解<code>@CrossOrigin</code> 当在网关处已经配置了跨域解决时，此时前端会提示：<code>but only one is allowed.</code> 即：重复处理跨域请求 因此只需要去掉这个<code>@CrossOrigin</code>即可</p><p>SpringCloud网关Gateway跨域处理，兼容IE 发布于2021-04-22 15:29:15阅读 7170 原文地址：<a href="https://www.aiprose.com/blog/139" target="_blank" rel="noreferrer">https://www.aiprose.com/blog/139</a></p><p>跨域是一个前后端分离开发无法避免的坑，尤其是要兼容ie。之前单项目的时候，都是在后台直接配置cors就好了，或者在nginx中配置，但是微服务要是挨个都配置，代码量大，也不是很优雅。所以我们一般都会在网关配置跨域处理，以下是我的方案，项目亲测可用。</p><p>springboot版本：2.3.9.RELEASE</p><p>@Configuration public class CorsWebFilter implements WebFilter { private static final String ALL = &quot;*&quot;; private static final String MAX_AGE = &quot;18000L&quot;;</p><p>@Override public Mono&lt;Void&gt; filter(ServerWebExchange ctx, WebFilterChain chain) { ServerHttpRequest request = ctx.getRequest(); if (!CorsUtils.isCorsRequest(request)) { return chain.filter(ctx); } String path = request.getPath().value(); ServerHttpResponse response = ctx.getResponse(); if (&quot;/favicon.ico&quot;.equals(path)) { response.setStatusCode(HttpStatus.OK); return Mono.empty(); } HttpHeaders requestHeaders = request.getHeaders(); HttpMethod requestMethod = requestHeaders.getAccessControlRequestMethod(); HttpHeaders headers = response.getHeaders(); headers.add(HttpHeaders.ACCESS_CONTROL_ALLOW_ORIGIN, requestHeaders.getOrigin()); if (requestMethod != null) { headers.add(HttpHeaders.ACCESS_CONTROL_ALLOW_HEADERS, requestHeaders.getAccessControlRequestHeaders().toString().replace(&quot;[&quot;, &quot;&quot;).replace(&quot;]&quot;, &quot;&quot;)); headers.add(HttpHeaders.ACCESS_CONTROL_ALLOW_METHODS, requestMethod.name()); } headers.add(HttpHeaders.ACCESS_CONTROL_ALLOW_CREDENTIALS, &quot;true&quot;); headers.add(HttpHeaders.ACCESS_CONTROL_EXPOSE_HEADERS, ALL); headers.add(HttpHeaders.ACCESS_CONTROL_MAX_AGE, MAX_AGE); if (request.getMethod() == HttpMethod.OPTIONS) { response.setStatusCode(HttpStatus.OK); return Mono.empty(); } return chain.filter(ctx); } } 复制 一些注意事项： 1.设置ACCESS_CONTROL_ALLOW_HEADERS的时候不能把请求的数组AccessControlRequestHeaders直接给塞进去，否则ie会报错，这里需要转成String类型。 2.OPTION请求过来的时候会带着AccessControlRequestHeaders，我们在OPTION返回的时候设置跨域的请求头，下次正式请求过来的时候，就不需要设置了，因为OPTION预检验是通过的。 3.ACCESS_CONTROL_ALLOW_HEADERS设置*的话，ie上是会报错的。报错异常信息为：Access-Control-Allow-Headers 列表中不存在请求标头 x-requested-with。 4.如果发现设置的跨域响应头是重复的，那么你需要去重，代码在下方。</p><p>@Component public class CorsResponseHeaderFilter implements GlobalFilter, Ordered {</p><p>@Override public int getOrder() { // 指定位于 NettyWriteResponseFilter 处理完响应体后移除重复 CORS 响应头 return NettyWriteResponseFilter.WRITE_RESPONSE_FILTER_ORDER + 1; }</p><p>@Override @SuppressWarnings(&quot;serial&quot;) public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) { return chain.filter(exchange).then(Mono.defer(() -&gt; { exchange.getResponse().getHeaders().entrySet().stream() .filter(kv -&gt; (kv.getValue() != null &amp;&amp; kv.getValue().size() &gt; 1)) .filter(kv -&gt; (kv.getKey().equals(HttpHeaders.ACCESS_CONTROL_ALLOW_ORIGIN) || kv.getKey().equals(HttpHeaders.ACCESS_CONTROL_ALLOW_CREDENTIALS))) .forEach(kv -&gt; kv.setValue(new ArrayList&lt;String&gt;() {{ add(kv.getValue().get(0)); }})); return chain.filter(exchange); })); } }</p></div>`,1)])])}const q=t(i,[["render",a]]);export{g as __pageData,q as default};
